<?php require_once '../config.php'; requireLogin(); header('Content-Type: application/json; charset=utf-8');try{$uid=getUserId();$t=getAccessToken();if($_SERVER['REQUEST_METHOD']==='POST'){if(($_POST['action']??'')==='delete'){sb_delete('user_words',['id'=>(int)($_POST['id']??0),'user_id'=>$uid],$t);echo json_encode(['success'=>true],JSON_UNESCAPED_UNICODE);exit;}$en=trim($_POST['english']??'');$fa=trim($_POST['farsi']??'');if($en===''||$fa==='')throw new RuntimeException('هر دو فیلد الزامی است');sb_insert('user_words',['user_id'=>$uid,'english'=>$en,'farsi'=>$fa],$t,false);echo json_encode(['success'=>true],JSON_UNESCAPED_UNICODE);exit;}$rows=sb_query('user_words',['select'=>'id,english,farsi,ticks,learned,in_re_review,date_added','user_id'=>'eq.'.$uid,'order'=>'date_added.desc,id.desc','limit'=>2000],$t);echo json_encode(['success'=>true,'words'=>array_map(fn($w)=>['id'=>(int)$w['id'],'english'=>$w['english'],'farsi'=>$w['farsi'],'ticks'=>(int)$w['ticks'],'learned'=>(bool)$w['learned'],'in_re_review'=>(bool)$w['in_re_review']],$rows)],JSON_UNESCAPED_UNICODE);}catch(Throwable $e){http_response_code(400);echo json_encode(['success'=>false,'error'=>sb_error_message($e)],JSON_UNESCAPED_UNICODE);}